CREATE TABLE "GuestCareProfile" ("guestId" TEXT NOT NULL,"emailConsent" BOOLEAN NOT NULL DEFAULT false,"contactPreference" TEXT NOT NULL DEFAULT 'any',"wantsPrayer" BOOLEAN NOT NULL DEFAULT false,"wantsPastoralContact" BOOLEAN NOT NULL DEFAULT false,"ministryInterest" TEXT,"hospitalitySteps" JSONB NOT NULL DEFAULT '[]',"referralStatus" TEXT NOT NULL DEFAULT 'none',"referralMinistry" TEXT,"referralNote" TEXT,"updatedById" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GuestCareProfile_pkey" PRIMARY KEY ("guestId"));